### DataLoader Pattern (Prevents N+1 Queries)

```python
import strawberry
from strawberry.dataloader import DataLoader
from typing import List

# Without DataLoader (N+1 problem)
@strawberry.type
class User:
    id: int
    name: str

    @strawberry.field
    def posts(self) -> List['Post']:
        # This runs a query for EACH user!
        # If you fetch 100 users, this runs 100 queries!
        return db.query(Post).filter(Post.user_id == self.id).all()

# With DataLoader (batches queries)
async def load_posts_batch(user_ids: List[int]) -> List[List['Post']]:
    """Fetch posts for multiple users in ONE query"""
    posts = db.query(Post).filter(Post.user_id.in_(user_ids)).all()

    # Group by user_id
    posts_by_user = {uid: [] for uid in user_ids}
    for post in posts:
        posts_by_user[post.user_id].append(post)

    return [posts_by_user[uid] for uid in user_ids]

post_loader = DataLoader(load_fn=load_posts_batch)

@strawberry.type
class User:
    id: int
    name: str

    @strawberry.field
    async def posts(self) -> List['Post']:
        # DataLoader batches all requests and makes ONE query!
        return await post_loader.load(self.id)

# Query complexity limiting
from strawberry.extensions import QueryDepthLimiter

schema = strawberry.Schema(
    query=Query,
    extensions=[
        QueryDepthLimiter(max_depth=5)  # Prevent deeply nested queries
    ]
)
